sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var baseUrl = gs.getProperty('glide.servlet.uri', '');
    if (baseUrl.endsWith('/')) {
        baseUrl = baseUrl.slice(0, -1);
    }

    var bookPath = gs.getProperty('x_2223823_apollo_0.url.book_appointment', '/esc?id=book_appointment');
    var doctorPath = gs.getProperty('x_2223823_apollo_0.url.find_doctor', '/esc?id=find_doctor');
    var servicesPath = gs.getProperty('x_2223823_apollo_0.url.our_services', '/esc?id=apollo_portal');

    var bookUrl = bookPath.indexOf('http') === 0 ? bookPath : baseUrl + bookPath;
    var doctorUrl = doctorPath.indexOf('http') === 0 ? doctorPath : baseUrl + doctorPath;
    var servicesUrl = servicesPath.indexOf('http') === 0 ? servicesPath : baseUrl + servicesPath;

    var linkStyle = 'color: #ffffff; text-decoration: none; font-weight: 500; padding: 0 8px;';

    template.print('<a style="' + linkStyle + '" href="' + bookUrl + '">Book Appointment</a>');
    template.print('<span style="color: rgba(255,255,255,0.4);">|</span>');
    template.print('<a style="' + linkStyle + '" href="' + doctorUrl + '">Find a Doctor</a>');
    template.print('<span style="color: rgba(255,255,255,0.4);">|</span>');
    template.print('<a style="' + linkStyle + '" href="' + servicesUrl + '">Our Services</a>');
})(current, template, email, email_action, event);
